CREATE OR REPLACE FUNCTION public.chat_send(_peer uuid,_group uuid,_body text,_client uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE mid uuid; BEGIN IF NOT public.messaging_allowed('chat.create') OR length(trim(_body)) NOT BETWEEN 1 AND 4000 THEN RAISE EXCEPTION 'Message not permitted'; END IF; IF _group IS NOT NULL THEN IF NOT public.chat_group_access(_group) THEN RAISE EXCEPTION 'Group access denied'; END IF; ELSE IF NOT public.can_chat_with(_peer) THEN RAISE EXCEPTION 'Recipient access denied'; END IF; END IF; INSERT INTO public.chat_messages(sender_id,recipient_id,group_id,body,client_id) VALUES(auth.uid(),CASE WHEN _group IS NULL THEN _peer ELSE auth.uid() END,_group,trim(_body),_client) ON CONFLICT(sender_id,client_id) WHERE client_id IS NOT NULL DO NOTHING RETURNING id INTO mid; IF mid IS NULL THEN SELECT id INTO mid FROM public.chat_messages WHERE sender_id=auth.uid() AND client_id=_client; END IF; RETURN mid; END $$;
CREATE OR REPLACE FUNCTION public.chat_read(_peer uuid,_group uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF _group IS NOT NULL THEN IF NOT public.chat_group_access(_group) THEN RAISE EXCEPTION 'Group access denied'; END IF; UPDATE public.chat_group_members SET read_at=now() WHERE group_id=_group AND user_id=auth.uid(); ELSE IF NOT public.can_chat_with(_peer) THEN RAISE EXCEPTION 'Recipient access denied'; END IF; UPDATE public.chat_messages SET read_at=now() WHERE group_id IS NULL AND sender_id=_peer AND recipient_id=auth.uid() AND read_at IS NULL; END IF; END $$;
GRANT EXECUTE ON FUNCTION public.chat_send(uuid,uuid,text,uuid),public.chat_read(uuid,uuid) TO authenticated;